def transform(grid):
    n=len(grid)
    lines=[r for r,row in enumerate(grid) if len(set(row))==1 and row[0] not in (0,5,9)]
    objects=[]
    for k,r in enumerate(lines):
        color=grid[r][0]
        end=lines[k+1] if k+1<len(lines) else next((q for q in range(r+1,n) if grid[q]==[9]*len(grid[q])),n)
        cells=[q for q in range(r+1,end) if color in grid[q]]
        if cells:
            objects.append((color,len(cells)))
    out=[[0,0,0,9,0] for _ in range(3)]
    out[1][4]=5
    for idx,(color,height) in enumerate(objects[:3]):
        row=3-len(objects[:3])+idx
        for col in range(min(3,sum(grid[q].count(color)==3 for q in cells))):
            out[row][col]=color
    return out

